     "event": "CARD_USAGE",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.3,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBME-R08-02",
   "status": "OK",
   "label": "KB국민카드 우대이율",
   "source": {
    "quote": "[2]KB국민카드 우대이율 | 신규일로부터 3개월이 되는 날이 속한 달에 30만원 이상의 KB국민카드 (신용/체크, 개인/기업, KB국민BC카드 포함) 이용실적주 (매입전표만 인정)이 있는 경우 | 연0.1%p"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "last"
      }
     }
