   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-KBME-R08-03",
   "status": "OK",
   "label": "사업성공우대이율",
   "source": {
