   },
   "condition": {
    ">=": [
     {
      "var": "contract.amount"
     },
     10000000
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  }
 ]
