{
 "rules": [
  {
   "rule_id": "R-KBMY-S2-R08-01",
   "status": "OK",
   "label": "급여이체 우대이율",
   "source": {
    "quote": "1 | 급여이체 | 이 적금의 신규일이 포함된 달부터 3개월이 경과한 달까지 50만원 이상 급여이체 실적주1)이 발생한 월수가 1개월 이상인 경우"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.start_date",
       "offset_months": 3,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "count_distinct_months": {
       "event": "SALARY_TRANSFER",
       "within": {
        "ref": "$window"
       },
       "where": {
        "min_amount": 500000
       }
      }
     },
     {
      ">=": [
       {
        "count_distinct_months": {
