        "operator": "+",
        "value": 1
      },
      "operator": "/",
      "value": 2
    },
    "unit": "PERCENT",
    "operator": "*",
    "value": {
      "var": "contract.interest_rate",
      "operator": "/",
      "value": 12
    }
   }
  }
 ]
}

