   "source": {
    "quote": "▪ 자유적립식: 입금금액 × 약정이율 × 일수(입금일~만기일 전일)/365"
   },
   "condition": {
    "equal": [
     {
      "var": "contract.product_type"
     },
     "FREE_SAVING"
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": {
      "formula": "account.balance * contract.interest_rate * ((contract.maturity_date - contract.start_date).days / 365)"
    },
    "unit": "DAY"
   }
  },
  {
   "rule_id": "R-KBHAP-S2-R11-02",
   "status": "OK",
   "label": "정액적립식 이자 계산",
   "source": {
    "quote": "▪ 정액적립식: {월저축금 × 계약월수 × (계약월수+1)/2} × (연이율/12)"
   },
   "condition": {
    "equal": [
     {
      "var": "contract.product_type"
     },
     "FIXED_SAVING"
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": {
      "formula": "contract.monthly_amount * contract.monthly_count * (contract.monthly_count + 1) / 2 * (contract.interest_rate / 12)"
    },
    "unit": "MONTH"
   }
  }
 ]
}

